enum EGalleryMsgType {
  /**文件格式错误 */
  typeError,
  /**部分文件格式错误 */
  typeErrors,
  /**文件超出最大尺寸 */
  overSize,
  /**部分文件超出最大尺寸 */
  overSizes,
  /**文件小于最小尺寸 */
  lessSize,
  /**部分文件小于最小尺寸 */
  lessSizes,
  /**文件名称为空 */
  nameEmpty,
  /**部分文件名称为空 */
  namesEmpty,
  /**判断图片尺寸加载失败 */
  damagedError,
  /**判断部分图片尺寸加载失败 */
  damagedErrors,
  /**图片宽高大于512 */
  moreThen512Error,
  /**图片宽高小于128，需求去掉LOGO上传最小限制，之前是128 */
  lessThen128Error,
  /**图库容量不足 */
  capacityNotEnough,
  /**图片最大支持{number}张，资源不足，无法导入 */
  maxNumberError,
  /** 单个乘积超出限制 */
  overProductSize,
  /** 批量乘积超出限制 */
  overProductSizes,
  /** 单个图片文件过大 */
  overFileSize,
  /** 部分图片文件过大 */
  overFileSizes,
}
